uint64_t pk_entry(void *mem) {
  const uint8_t *m = (const uint8_t *)mem;
  uint64_t bit_len = 0;
  uint32_t i;
  for (i = 0; i < 8; i++) bit_len |= (uint64_t)m[i] << (8 * i);
  pk_katran_flow_result_t out = {0};
  pk_katran_flow_parse_core(m + 8, bit_len, &out);
  return ((uint64_t)out.outcome << 56) | ((uint64_t)out.reason << 48) | (out.consumed_bits & 0xFFFFFFFFFFFFULL);
}
